insert into public.regions ("id", "name", "capital", "abbreviation", "grid", "span", "blurb", "destinations", "festivals") values
('greater-accra', 'Greater Accra', 'Accra', 'GA', '[3, 0]', '[1, 1]', 'Ghana''s national capital and economic heartbeat, home of the Independence Arch and the coastal Ga heartland.', '["black-star-square"]', '["homowo-festival", "asafotufiam-festival"]'),
('central', 'Central Region', 'Cape Coast', 'CE', '[3, 2]', '[1, 1]', 'Historic Cape Coast and Elmina castles, the Kakum rainforest canopy, and the Effutu deer-hunting tradition.', '["cape-coast-castle", "kakum-national-park", "elmina-castle"]', '["aboakyer-festival", "bakatue-festival", "fetu-afahye-festival"]'),
('western', 'Western Region', 'Sekondi-Takoradi', 'WE', '[2, 2]', '[1, 1]', 'Ghana''s oil and mineral coast, home of the stilt village of Nzulezo and lush rainforests.', '["nzulezo-stilt-village"]', '[]'),
('western-north', 'Western North', 'Sefwi Wiawso', 'WN', '[2, 1]', '[1, 1]', 'Cocoa country and gold-rich forests of the Sefwi people in western Ghana.', '[]', '[]'),
('ashanti', 'Ashanti Region', 'Kumasi', 'AH', '[2, 0]', '[1, 1]', 'The royal heartland of the Asante Kingdom, famed for the Manhyia Palace and Bonwire kente weaving.', '["bonwire-kente-village"]', '[]'),
('eastern', 'Eastern Region', 'Koforidua', 'ER', '[1, 1]', '[1, 1]', 'The green garden region of Aburi, twin Boti waterfalls, and the Krobo Dipo puberty rites.', '["boti-waterfalls", "aburi-botanical-gardens"]', '["dipo-festival", "kloyo-sikplemi-festival"]'),
('volta', 'Volta Region', 'Ho', 'VR', '[1, 2]', '[1, 1]', 'The Ewe heartland of the Anlo people — monkey sanctuaries, Wli waterfall, Mount Afadjato and Mount Gemi.', '["tafi-atome-monkey-sanctuary", "wli-waterfall", "mount-afadjato"]', '["hogbetsotso-festival"]'),
('oti', 'Oti Region', 'Dambai', 'OT', '[1, 3]', '[1, 1]', 'A northern-Volta borderland along Lake Volta, home of the Nkonya people.', '[]', '[]'),
